-- Project money is independently controlled by the project's appointed committee.
begin;
insert into public.project_settings(project_id) select id from public.projects on conflict do nothing;
update public.project_settings set policy='{"mode":"fixed","amount":0,"dueDay":10,"categories":[],"independentReview":true,"approvalThreshold":0,"special":0}' where policy='{}' and not enabled;
create or replace function private.project_relationship(uid uuid,pid uuid) returns boolean language sql stable security definer set search_path='' as $$select private.project_member(uid,pid) or exists(select 1 from public.ownership o join public.flats f on f.id=o.flat_id where o.user_id=uid and f.project_id=pid and not f.is_test);$$;
create table private.project_attachment_data(id uuid primary key references public.project_attachments(id),content text not null);
alter table private.project_attachment_data enable row level security;
revoke all on private.project_attachment_data from public,anon,authenticated;
create table public.service_coverage(project_id uuid references public.projects(id),category_id text references public.service_catalog(id),enabled boolean not null default false,primary key(project_id,category_id));
alter table public.service_coverage enable row level security;
grant select on public.service_coverage to authenticated;
create policy coverage_index on public.service_coverage for select to authenticated using(true);
alter table public.service_requests add column request_key text;
create unique index service_request_retry on public.service_requests(user_id,request_key) where request_key is not null;
revoke insert on public.service_requests from authenticated;
-- Closed periods are never edited. A correction is posted to an open period.
create function private.project_open_day(pid uuid,d date) returns void language plpgsql stable security definer set search_path='' as $$begin if d is null or d>(now() at time zone 'Asia/Kolkata')::date then raise exception 'Use an actual, non-future transaction date';end if;if exists(select 1 from public.billing_periods where project_id=pid and month=date_trunc('month',d)::date and state='closed') then raise exception 'This month is closed; use an open correction period';end if;end;$$;
create function private.project_history_add(pid uuid,kind text,target uuid,details text) returns void language sql security definer set search_path='' as $$insert into public.project_history(project_id,actor,kind,target,details) values(pid,auth.uid(),kind,target,left(details,1000));$$;
create function private.project_credit(pid uuid,uid uuid,cutoff date default '9999-12-01') returns bigint language sql stable security definer set search_path='' as $$select coalesce((select sum(amount-allocated) from public.project_receipts where project_id=pid and user_id=uid and received_on<cutoff+interval '1 month'),0)-coalesce((select sum(amount) from public.credit_allocations where project_id=pid and user_id=uid and created_at<cutoff+interval '1 month'),0);$$;
create function private.invoice_card(i public.flat_invoices,cutoff date default '9999-12-01') returns jsonb language sql stable security definer set search_path='' as $$with n as(select coalesce((select sum(a.amount) from public.invoice_adjustments a where invoice_id=i.id and effective_month<=cutoff),0) adjustment,coalesce((select sum(r.allocated) from public.project_receipts r join public.payment_submissions s on s.id=r.submission_id where s.invoice_id=i.id and r.received_on<cutoff+interval '1 month'),0)+coalesce((select sum(amount) from public.credit_allocations where invoice_id=i.id and created_at<cutoff+interval '1 month'),0) paid) select to_jsonb(i)||jsonb_build_object('month',to_char(p.month,'YYYY-MM'),'state',p.state,'label',f.label,'adjustment',n.adjustment,'paid',n.paid,'balance',i.amount+n.adjustment-n.paid,'status',case when n.paid>=i.amount+n.adjustment then 'paid' when n.paid>0 then 'partially paid' when i.due_date<(now() at time zone 'Asia/Kolkata')::date then 'overdue' else 'due' end,'adjustments',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('created',a.created_at,'effective_month',to_char(a.effective_month,'YYYY-MM'))) from public.invoice_adjustments a where a.invoice_id=i.id and effective_month<=cutoff),'[]')) from public.billing_periods p join public.flats f on f.id=i.flat_id cross join n where p.id=i.period_id;$$;
create function private.project_accounts(pid uuid,m date) returns jsonb language plpgsql stable security definer set search_path='' as $$declare s public.project_settings;bp public.billing_periods;opening bigint;received bigint;paid bigint;transfer bigint;res bigint;expenses bigint;billed bigint;opening_dues bigint;receivable bigint;payable bigint;begin
 select * into s from public.project_settings where project_id=pid;select * into bp from public.billing_periods where project_id=pid and month=m;
 if bp.state='closed' and bp.snapshot is not null then return bp.snapshot;end if;
 select s.opening_cash+coalesce(sum(amount) filter(where fund='general' and paid_on<m),0),coalesce(sum(amount) filter(where fund='general' and paid_on>=m and paid_on<m+interval '1 month' and amount>0 and source not like 'transfer:%'),0),-coalesce(sum(amount) filter(where fund='general' and paid_on>=m and paid_on<m+interval '1 month' and amount<0 and source not like 'transfer:%'),0),coalesce(sum(amount) filter(where fund='general' and paid_on>=m and paid_on<m+interval '1 month' and source like 'transfer:%'),0),s.opening_reserve+coalesce(sum(amount) filter(where fund='reserve' and paid_on<m+interval '1 month'),0) into opening,received,paid,transfer,res from public.project_cash where project_id=pid;
 select coalesce(sum(amount),0) into expenses from public.project_expense_bills where project_id=pid and period=m and status='approved';
 select coalesce(sum(i.amount),0) into billed from public.flat_invoices i join public.billing_periods p on p.id=i.period_id where i.project_id=pid and p.month=m and p.state in ('published','closed');
 billed:=billed+coalesce((select sum(a.amount) from public.invoice_adjustments a join public.flat_invoices i on i.id=a.invoice_id join public.billing_periods p on p.id=i.period_id where a.project_id=pid and a.effective_month=m and p.state in ('published','closed')),0);
 select coalesce(sum((ln->>'amount')::bigint),0) into opening_dues from public.flat_invoices i join public.billing_periods p on p.id=i.period_id cross join lateral jsonb_array_elements(i.lines) ln where i.project_id=pid and p.month=m and p.state in ('published','closed') and ln->>'label'='Verified opening dues';
 billed:=billed-opening_dues;
 select coalesce(sum((private.invoice_card(i,m)->>'balance')::bigint),0) into receivable from public.flat_invoices i join public.billing_periods p on p.id=i.period_id where i.project_id=pid and p.month<=m and p.state in ('published','closed');
 select coalesce(sum(amount),0) into payable from public.project_expense_bills where project_id=pid and period<=m and status='approved';payable:=payable-coalesce((select sum(amount) from public.project_expense_payments where project_id=pid and paid_on<m+interval '1 month'),0);
 return jsonb_build_object('projectId',pid,'month',to_char(m,'YYYY-MM'),'state',coalesce(bp.state,'unbilled'),'opening',opening,'receipts',received,'payments',paid,'closing',opening+received-paid+transfer,'reserveTransfer',transfer,'reserve',res,'advances',coalesce((select sum(amount-allocated) from public.project_receipts where project_id=pid and received_on<m+interval '1 month'),0)-coalesce((select sum(amount) from public.credit_allocations where project_id=pid and created_at<m+interval '1 month'),0),'receivables',receivable,'payables',payable,'billed',billed,'openingDues',opening_dues,'expenses',expenses,'accrualSurplus',billed-expenses,'categories',coalesce((select jsonb_object_agg(category,total) from (select category,sum(amount) total from public.project_expense_bills where project_id=pid and period=m and status='approved' group by category) x),'{}'),'budgets',coalesce((select jsonb_agg(payload) from public.project_operations where project_id=pid and kind='budget'),'[]'));
 end;$$;
create function private.project_bill_card(b public.project_expense_bills,committee boolean) returns jsonb language sql stable security definer set search_path='' as $$with n as(select b.amount+coalesce((select sum(c.amount) from public.project_expense_bills c where c.project_id=b.project_id and c.status='approved' and c.details->>'correctionOf'=b.id::text),0) adjusted,coalesce((select sum(amount) from public.project_expense_payments where bill_id=b.id),0) paid) select (case when committee then to_jsonb(b)||jsonb_build_object('original_amount',b.amount,'adjusted_amount',n.adjusted,'created',b.created_at) else jsonb_build_object('id',b.id,'project_id',b.project_id,'category',b.category,'description',b.description,'status',b.status,'redacted_attachment_id',case when exists(select 1 from public.project_attachments a where a.id=b.redacted_attachment_id and a.scan_state='clean' and a.visibility='redacted') then b.redacted_attachment_id else null end) end)||jsonb_build_object('period',to_char(b.period,'YYYY-MM'),'amount',n.adjusted,'paid',n.paid) from n;$$;
create function private.project_workspace(pid uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare uid uuid:=auth.uid();c boolean:=private.project_committee(pid);s public.project_settings;begin
 if not private.project_relationship(uid,pid) then raise exception 'Verified ownership or residence in this project required';end if;select * into s from public.project_settings where project_id=pid;
 return jsonb_build_object('project',(select to_jsonb(p) from public.projects p where p.id=pid),'committeeMode',c,'settings',case when c then to_jsonb(s) else jsonb_build_object('enabled',s.enabled,'start_date',s.start_date,'policy',s.policy) end,'appointment',(select to_jsonb(a) from public.committee_appointments a where a.project_id=pid and a.user_id=uid and a.status='active' and a.starts<=(now() at time zone 'Asia/Kolkata')::date and a.ends>(now() at time zone 'Asia/Kolkata')::date),'committee',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('name',p.display_name)) from public.committee_appointments a join public.profiles p on p.id=a.user_id where a.project_id=pid and a.status='active' and a.starts<=(now() at time zone 'Asia/Kolkata')::date and a.ends>(now() at time zone 'Asia/Kolkata')::date and private.project_relationship(a.user_id,pid)),'[]'),
 'invoices',coalesce((select jsonb_agg(private.invoice_card(i) order by p.month desc,f.label) from public.flat_invoices i join public.billing_periods p on p.id=i.period_id join public.flats f on f.id=i.flat_id where i.project_id=pid and (c or i.payer_id=uid and p.state in ('published','closed'))),'[]'),
 'periods',coalesce((select jsonb_agg(jsonb_build_object('id',id,'month',to_char(month,'YYYY-MM'),'state',state) order by month desc) from public.billing_periods where project_id=pid and (c or state in ('published','closed'))),'[]'),
 'bills',coalesce((select jsonb_agg(private.project_bill_card(b,c) order by b.created_at desc) from public.project_expense_bills b where b.project_id=pid and (c or b.status='approved' and exists(select 1 from public.billing_periods p where p.project_id=pid and p.month=b.period and p.state in ('published','closed')))),'[]'),
 'submissions',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('created',p.created_at) order by p.created_at desc) from public.payment_submissions p where p.project_id=pid and (c or p.user_id=uid)),'[]'),
 'receipts',coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('date',r.received_on) order by received_on desc) from public.project_receipts r where r.project_id=pid and (c or r.user_id=uid)),'[]'),'credit',private.project_credit(pid,uid),
 'questions',coalesce((select jsonb_agg((to_jsonb(q)-'attachment_id')||jsonb_build_object('faq_consent',case when q.faq_consent then 1 else 0 end,'created',q.created_at,'attachment_id',case when c or q.user_id=uid then q.attachment_id else null end,'replies',coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('name',pr.display_name,'created',r.created_at) order by r.created_at) from public.project_replies r join public.profiles pr on pr.id=r.user_id where r.question_id=q.id),'[]'),'history',coalesce((select jsonb_agg(jsonb_build_object('kind',h.kind,'details',h.details,'created',h.created_at) order by h.created_at) from public.project_history h where h.target=q.id and h.project_id=pid),'[]')) order by q.created_at desc) from public.project_questions q where q.project_id=pid and (c or q.user_id=uid or q.visibility='project')),'[]'),
 'operations',coalesce((select jsonb_agg(to_jsonb(o)||jsonb_build_object('created',o.created_at,'votes',coalesce((select jsonb_agg(jsonb_build_object('choice',v.choice,'count',v.n)) from (select choice,count(*) n from public.project_votes where operation_id=o.id group by choice) v),'[]')) order by o.created_at desc) from public.project_operations o where o.project_id=pid and (c or o.kind in ('notice','meeting','asset','faq','poll'))),'[]'),
 'flats',case when c then coalesce((select jsonb_agg(to_jsonb(f)||coalesce(to_jsonb(l)-'project_id'-'flat_id','{}')) from public.flats f left join public.project_flat_liability l on l.flat_id=f.id where f.project_id=pid and not f.is_test),'[]') else '[]'::jsonb end,
 'eligiblePayers',case when c then coalesce((select jsonb_agg(x) from (select distinct pr.id,pr.display_name name,f.label,f.id flat_id from public.profiles pr cross join public.flats f where f.project_id=pid and not f.is_test and (exists(select 1 from public.ownership where user_id=pr.id and flat_id=f.id) or exists(select 1 from public.memberships m where m.user_id=pr.id and m.flat_id=f.id and m.status='approved' and m.move_in<=now() and (m.move_out is null or m.move_out>now())))) x),'[]') else '[]'::jsonb end,
 'history',case when c then coalesce((select jsonb_agg(to_jsonb(h)||jsonb_build_object('created',h.created_at) order by h.created_at desc) from (select * from public.project_history where project_id=pid order by created_at desc limit 100) h),'[]') else '[]'::jsonb end,'renewals',coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'renewal',payload->>'renewal')) from public.project_operations where project_id=pid and kind='asset' and nullif(payload->>'renewal','')::date<=(now() at time zone 'Asia/Kolkata')::date+30),'[]'),'linkableServices',case when c then coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'description',r.description,'label',f.label)) from public.service_requests r join public.flats f on f.id=r.flat_id where f.project_id=pid and r.user_id=uid and r.status='completed' and not exists(select 1 from public.project_expense_bills where service_request_id=r.id)),'[]') else '[]'::jsonb end);
end;$$;
create function private.op_text(v text,n integer) returns text language plpgsql immutable set search_path='' as $$begin if v is null or length(trim(v)) not between 1 and n then raise exception 'Enter a value between 1 and % characters',n;end if;return trim(v);end;$$;
create function private.op_amount(v text,minimum bigint default 0,maximum bigint default 10000000000) returns bigint language plpgsql immutable set search_path='' as $$declare n bigint;begin n:=v::bigint;if n is null or n<minimum or n>maximum then raise exception 'Amount or quantity outside permitted range';end if;return n;end;$$;
create function private.op_month(v text) returns date language plpgsql immutable set search_path='' as $$begin if v is null or v !~ '^\d{4}-(0[1-9]|1[0-2])$' then raise exception 'Use YYYY-MM';end if;return (v||'-01')::date;end;$$;
create function private.project_own_attachment(pid uuid,aid uuid,redacted boolean default false) returns void language plpgsql stable security definer set search_path='' as $$begin if aid is not null and not exists(select 1 from public.project_attachments where id=aid and project_id=pid and owner_id=auth.uid() and (not redacted or visibility='redacted')) then raise exception 'Use your own attachment in this project';end if;end;$$;
create function private.service_card(r public.service_requests) returns jsonb language sql stable security definer set search_path='' as $$select to_jsonb(r)||jsonb_build_object('category',c.name,'category_id',r.category_id,'project',p.name,'label',f.label,'preferred',r.preferred_visit,'created',r.created_at,'technician',t.name,'hosted',true,'history',coalesce((select jsonb_agg(jsonb_build_object('status',h.status,'note',h.note,'created',h.created_at) order by h.created_at,h.id) from public.service_history h where h.request_id=r.id),'[]')) from public.flats f join public.projects p on p.id=f.project_id join public.service_catalog c on c.id=r.category_id left join public.technicians t on t.id=r.technician_id where f.id=r.flat_id;$$;
create function public.operations_context() returns jsonb language plpgsql stable security definer set search_path='' as $$declare uid uuid:=auth.uid();role text;begin
 if uid is null then raise exception 'Sign in';end if;select s.role into role from private.staff s where s.user_id=uid;
 return jsonb_build_object('hosted',true,'owner',coalesce(role='platform',false),'serviceOperator',coalesce(role in ('platform','services','technician'),false),'user',jsonb_build_object('id',uid,'name',(select display_name from public.profiles where id=uid),'role',coalesce(role,'resident')),'projects',(select coalesce(jsonb_agg(to_jsonb(p) order by p.name),'[]') from public.projects p),'memberships',coalesce((select jsonb_agg(to_jsonb(m)||jsonb_build_object('project',p.name,'project_id',f.project_id,'label',f.label)) from public.memberships m join public.flats f on f.id=m.flat_id join public.projects p on p.id=f.project_id where m.user_id=uid and m.status='approved' and not f.is_test and m.move_in<=now() and (m.move_out is null or m.move_out>now())),'[]'),'social',jsonb_build_object('services',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('projectIds',coalesce((select jsonb_agg(sc.project_id) from public.service_coverage sc where sc.category_id=c.id and sc.enabled and private.active_project(sc.project_id)),'[]'),'available',exists(select 1 from public.service_coverage sc where sc.category_id=c.id and sc.enabled and private.active_project(sc.project_id)))) from public.service_catalog c),'[]'),'requests',coalesce((select jsonb_agg(private.service_card(r) order by r.created_at desc) from public.service_requests r join public.flats f on f.id=r.flat_id where r.user_id=uid and not f.is_test),'[]')));
end;$$;
create function public.services_api(p_route text,p_method text default 'GET',p_body jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare uid uuid:=auth.uid();parts text[]:=string_to_array(p_route,'/');operator boolean:=private.staff_role(array['services','platform']);owner boolean:=private.staff_role(array['platform']);r public.service_requests;t public.technicians;target uuid;pid uuid;next text:=p_body->>'status';k text;id uuid;staff_uid uuid;begin
 if uid is null then raise exception 'Sign in';end if;
 if p_route='service-ops' and p_method='GET' then
 if not operator and not private.staff_role(array['technician']) then raise exception 'Service desk access required';end if;
 return jsonb_build_object('requests',coalesce((select jsonb_agg(private.service_card(r) order by r.created_at desc) from public.service_requests r join public.flats f on f.id=r.flat_id where not f.is_test and (operator or exists(select 1 from public.technicians t where t.id=r.technician_id and t.user_id=uid))),'[]'),'technicians',coalesce((select jsonb_agg(to_jsonb(t)) from public.technicians t where operator or t.user_id=uid),'[]'));end if;
 if p_route='service-setup' and owner then
 if p_method='GET' then return jsonb_build_object('coverage',coalesce((select jsonb_agg(to_jsonb(s)) from public.service_coverage s),'[]'),'technicians',coalesce((select jsonb_agg(to_jsonb(t)) from public.technicians t),'[]'),'categories',(select jsonb_agg(to_jsonb(c)) from public.service_catalog c));end if;
 if p_method<>'POST' then raise exception 'Method unavailable';end if;
 if p_body->>'action'='coverage' then insert into public.service_coverage(project_id,category_id,enabled) values((p_body->>'projectId')::uuid,p_body->>'categoryId',(p_body->>'enabled')::boolean) on conflict(project_id,category_id) do update set enabled=excluded.enabled;
 elsif p_body->>'action'='technician' then
 select id into staff_uid from auth.users where lower(email)=lower(private.op_text(p_body->>'email',254));if not found then raise exception 'Create this staff account in Supabase Auth first';end if;
 if exists(select 1 from private.staff where user_id=staff_uid and role<>'technician') then raise exception 'Existing staff role cannot be replaced here';end if;
 insert into private.staff(user_id,role) values(staff_uid,'technician') on conflict(user_id) do nothing;
 insert into public.technicians(user_id,name,trade,on_shift) values(staff_uid,private.op_text(p_body->>'name',80),p_body->>'trade',coalesce((p_body->>'onShift')::boolean,false)) on conflict(user_id) do update set name=excluded.name,trade=excluded.trade,on_shift=excluded.on_shift where not exists(select 1 from public.service_requests r where r.technician_id=technicians.id and r.status in ('assigned','en_route','in_progress'));
 if not found then raise exception 'Finish assigned jobs before editing technician details';end if;
 else raise exception 'Unknown setup action';end if;
 insert into private.audit(actor_id,action,target_id) values(uid,'services.setup',staff_uid);return jsonb_build_object('ok',true);end if;
 if p_route='insta-services' and p_method='POST' then
 target:=(p_body->>'flatId')::uuid;select f.project_id into pid from public.flats f where f.id=target and not f.is_test and exists(select 1 from public.memberships m where m.flat_id=f.id and m.user_id=uid and m.status='approved' and m.move_in<=now() and (m.move_out is null or m.move_out>now()));if not found then raise exception 'An approved residence at this flat is required';end if;
 k:=private.op_text(p_body->>'key',100);perform pg_advisory_xact_lock(hashtextextended(uid::text||k,0));
 select * into r from public.service_requests where user_id=uid and request_key=k;if found then if r.flat_id<>target or r.category_id<>p_body->>'categoryId' or r.description<>trim(p_body->>'description') or r.preferred_visit<>trim(p_body->>'preferred') or r.priority<>p_body->>'urgency' then raise exception 'Retry differs from original request';end if;return jsonb_build_object('id',r.id);end if;
 if not exists(select 1 from public.service_coverage where project_id=pid and category_id=p_body->>'categoryId' and enabled) then raise exception 'This service is not accepting requests for your project yet';end if;
 if (select count(*) from public.service_requests where user_id=uid and created_at>now()-interval '1 day')>=20 then raise exception 'Daily service request limit reached';end if;
 insert into public.service_requests(user_id,flat_id,category_id,description,preferred_visit,priority,request_key) values(uid,target,p_body->>'categoryId',private.op_text(p_body->>'description',1500),private.op_text(p_body->>'preferred',100),p_body->>'urgency',k) returning service_requests.id into id;
 insert into public.service_history(request_id,actor_id,status,note) values(id,uid,'requested','Request received; scope and visit require MDP confirmation');return jsonb_build_object('id',id);end if;
 if parts[1]='insta-services' and parts[2] is not null and p_method='PATCH' then
 target:=parts[2]::uuid;select * into r from public.service_requests where service_requests.id=target for update;if not found then raise exception 'Request unavailable';end if;
 if next=r.status then if not operator and r.user_id<>uid and not exists(select 1 from public.technicians where id=r.technician_id and user_id=uid) then raise exception 'Request unavailable';end if;return jsonb_build_object('ok',true);end if;
 if next='cancelled' then if not operator and r.user_id<>uid then raise exception 'Cannot cancel another resident request';end if;if r.status not in ('requested','assigned') then raise exception 'Contact the service desk once work is underway';end if;
 elsif next='assigned' then
 if not operator or r.status<>'requested' then raise exception 'Service desk assignment required';end if;
 if not exists(select 1 from public.memberships mm join public.flats ff on ff.id=mm.flat_id where mm.user_id=r.user_id and mm.flat_id=r.flat_id and mm.status='approved' and not ff.is_test and mm.move_in<=now() and (mm.move_out is null or mm.move_out>now())) then raise exception 'Residence is no longer eligible for dispatch';end if;
 select * into t from public.technicians where id=(p_body->>'technicianId')::uuid for update;
 if not found or not t.on_shift or t.trade<>r.category_id or not exists(select 1 from private.staff where user_id=t.user_id and role='technician') or exists(select 1 from public.service_requests where technician_id=t.id and status in ('assigned','en_route','in_progress')) then raise exception 'Choose an available, on-shift specialist for this trade';end if;
 update public.service_requests set technician_id=t.id where id=target;
 elsif (r.status='assigned' and next='en_route') or (r.status='en_route' and next='in_progress') or (r.status='in_progress' and next='completed') then
 if not private.staff_role(array['technician']) or not exists(select 1 from public.technicians where id=r.technician_id and user_id=uid) then raise exception 'Only the assigned technician can update this job';end if;
 else raise exception 'Invalid service transition';end if;
 update public.service_requests set status=next,updated_at=now() where id=target;
 insert into public.service_history(request_id,actor_id,status,note) values(target,uid,next,case when next='assigned' then 'Trade-matched specialist assigned by MDP' else 'Status updated' end);return jsonb_build_object('ok',true);end if;
 raise exception 'Service endpoint unavailable';end;$$;
-- New helper functions are callable only inside authenticated, validating RPCs.
do $$declare f record;begin for f in select p.oid::regprocedure signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='private' and p.proname in ('project_open_day','project_history_add','project_credit','invoice_card','project_accounts','project_bill_card','project_workspace','op_text','op_amount','op_month','project_own_attachment','service_card')) or (n.nspname='public' and p.proname in ('operations_context','services_api')) loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);if f.nspname='public' then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
commit;
